Method.Implementation:

	 try{
		do ##super()
		$$$TRACE("Connect to " _ ..ApplicationAddress)
		$$$TRACE("Service " _ ..TuxedoService)		
		set ..objCdrTuxService = ##class(org.ihc.itf.cdr.CdrHl7AddUpdate).%New(..JavaGateway,..ApplicationAddress, ..TuxedoService)		
     	set status = ..CheckObject()
	}catch err{
		$$$LOGERROR("Exception while Creating Tuxedo Service: " _err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)	    
	    Set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError(..%ConfigName," Exception while Creating Tuxedo Service: "_err.AsSystemError()_"::"_err.Data_"::"_err.Code)
	}

	Quit status

	 #DIM status AS %Status
	 set status = $$$OK
	 $$$TRACE("IHC.ITF.ITFCOMMON.CDR.Hl7LabResultToTuxService..Inside OnMessage method")
	 try{

	    if (..CheckObject() '= $$$OK) {
		   $$$TRACE("**** Object does not exists ****")
		   // Try to re intialize
		   set result = ..OnInit()
	       if (result '= $$$OK)
	       {
		      set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError("IHC.ITF.ITFCOMMON.Operation.CdrHl7AddUpdateOperation", "Failed. MMI#: " _pRequest.StringValue_ " ; Reason: " _ result)						
		      return status
	       }
	    } 

		$$$TRACE(" Calling Hl7 Add .."_pRequest.RawContent)

		set pResponse=##class(Ens.StringResponse).%New()
		$$$TRACE("After response setup.")
		Set pResponse.StringValue =  ..objCdrTuxService.callAddUpdate(pRequest.RawContent)
		$$$TRACE("After call")
		Set respData = pResponse.StringValue

		$$$TRACE(" Call after the hl7 add .."_respData)
		set indexMSA = $F(respData, "MSA|AA")    	  
    	if (indexMSA > 0){
		   $$$TRACE("SUCCESS!!!..Ack received from Hl7AddUpdate. "_respData) 
	       set indexZEX = $F(respData, "ZEX|")
	       if (indexZEX > 0){	    			 
	          set empiNum = $LISTGET($LISTFROMSTRING(respData,"|"),*)	    			
	    	  $$$TRACE(" empiNum: " _ empiNum)	    			
	       }
    	}		 		
	 }catch err{
	    $$$TRACE("Exception Calling hl7 add: " _ err)
	    set status = $$$ERROR("Exception in Hl7 add/update Operation") 
	 }
	 return status


$$$TRACE(" $$$$$$$$$$$$$$$ Inside OnTearDown() method...")

Set tSC = $$$OK

Try {		
	If $IsObject(..objCdrTuxService) {
		$$$TRACE("Disconnecting from CDR Tuxedo service...")
		Do ..objCdrTuxService.shutdownTuxService()		
		Set ..objCdrTuxService = $$$NULLOREF
	}
}
Catch {
	Set tSC = $$$EnsSystemError
}
Set tSC = ##super()
Quit tSC
